window.ScripturaLexicons.BDAG_PART_0186 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-01\" data-source=\"BDAG\" data-search=\"Κανά, ἡ topônimo feminino Caná, localidade da Galileia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κανά, ἡ</td><td>topônimo feminino</td><td>Caná, localidade da Galileia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-02\" data-source=\"BDAG\" data-search=\"Καναναῖος, ου, ὁ epíteto masculino cananeu; zelota BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καναναῖος, ου, ὁ</td><td>epíteto masculino</td><td>cananeu; zelota</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-03\" data-source=\"BDAG\" data-search=\"Κανανίτης, ου, ὁ gentílico masculino habitante de Caná BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κανανίτης, ου, ὁ</td><td>gentílico masculino</td><td>habitante de Caná</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-04\" data-source=\"BDAG\" data-search=\"Κανδάκη, ης, ἡ título feminino Candace, rainha etíope BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κανδάκη, ης, ἡ</td><td>título feminino</td><td>Candace, rainha etíope</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-05\" data-source=\"BDAG\" data-search=\"κανών, όνος, ὁ substantivo masculino regra; padrão; norma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κανών, όνος, ὁ</td><td>substantivo masculino</td><td>regra; padrão; norma</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-06\" data-source=\"BDAG\" data-search=\"Καπερναούμ remissão lexical veja Καφαρναούμ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καπερναούμ</td><td>remissão lexical</td><td>veja Καφαρναούμ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-07\" data-source=\"BDAG\" data-search=\"καπηλεύω verbo comerciar; mercadejar; adulterar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καπηλεύω</td><td>verbo</td><td>comerciar; mercadejar; adulterar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-08\" data-source=\"BDAG\" data-search=\"καπνός, οῦ, ὁ substantivo masculino fumaça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καπνός, οῦ, ὁ</td><td>substantivo masculino</td><td>fumaça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-09\" data-source=\"BDAG\" data-search=\"Καππαδοκία, ας, ἡ topônimo feminino Capadócia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καππαδοκία, ας, ἡ</td><td>topônimo feminino</td><td>Capadócia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-10\" data-source=\"BDAG\" data-search=\"καραδοκία, ας, ἡ substantivo feminino expectativa ardente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καραδοκία, ας, ἡ</td><td>substantivo feminino</td><td>expectativa ardente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-11\" data-source=\"BDAG\" data-search=\"καρδία, ας, ἡ substantivo feminino coração; vida interior BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καρδία, ας, ἡ</td><td>substantivo feminino</td><td>coração; vida interior</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-12\" data-source=\"BDAG\" data-search=\"καρδιογνώστης, ου, ὁ substantivo masculino conhecedor dos corações BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καρδιογνώστης, ου, ὁ</td><td>substantivo masculino</td><td>conhecedor dos corações</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-13\" data-source=\"BDAG\" data-search=\"καροῦχα, ας, ἡ substantivo feminino carruagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καροῦχα, ας, ἡ</td><td>substantivo feminino</td><td>carruagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-14\" data-source=\"BDAG\" data-search=\"καρπάσινος, η, ον adjetivo feito de linho fino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καρπάσινος, η, ον</td><td>adjetivo</td><td>feito de linho fino</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-15\" data-source=\"BDAG\" data-search=\"Κάρπος, ου, ὁ antropônimo masculino Carpo, cristão de Trôade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κάρπος, ου, ὁ</td><td>antropônimo masculino</td><td>Carpo, cristão de Trôade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-16\" data-source=\"BDAG\" data-search=\"καρπός, οῦ, ὁ substantivo masculino fruto; resultado; proveito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καρπός, οῦ, ὁ</td><td>substantivo masculino</td><td>fruto; resultado; proveito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-17\" data-source=\"BDAG\" data-search=\"καρποφορέω verbo frutificar; produzir fruto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καρποφορέω</td><td>verbo</td><td>frutificar; produzir fruto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-18\" data-source=\"BDAG\" data-search=\"καρποφόρος, ον adjetivo frutífero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καρποφόρος, ον</td><td>adjetivo</td><td>frutífero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-19\" data-source=\"BDAG\" data-search=\"καρτερέω verbo perseverar; suportar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καρτερέω</td><td>verbo</td><td>perseverar; suportar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0186-20\" data-source=\"BDAG\" data-search=\"[ἀπὸ] Καρυώτου remissão lexical veja Ἰσκαριώθ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">[ἀπὸ] Καρυώτου</td><td>remissão lexical</td><td>veja Ἰσκαριώθ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0186-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κανά, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(também <span class=\"greek\">Κανᾶ</span>, por exemplo em Tischendorf) indeclinável: Caná, nome de uma cidade na Galileia (cf. Josefo, Vi. 86), cuja localização já não pode ser determinada com segurança. Entre as possibilidades estão os locais atualmente conhecidos como Khirbet Qana, cerca de 14 km ao norte de Nazaré (RMackowski, ‘Scholars’ Qanah.’ A Re-examination of the Evidence in Favor of Khirbet Qanah: BZ 23, ’79, 278–84; Dalman, Orte3 108–14 [Eng. tr. 112f]); Kafr Kanna, também conhecida como Kefr Kenna, cerca de 5 km a nordeste de Nazaré (TSoiron, D. Evangelium u. d. hl. Stätten in Palästina 1929), de fácil acesso aos antigos peregrinos; e até ˓Ain Qana, 1½ km ao norte de Nazaré, perto de Reina (veja WSanday, Sacred Sites of the Gospels 1903, 24, n.)—a primeira hipótese conta com maior apoio dos estudiosos. Lugar do primeiro milagre de Jesus em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:1</a>, 11 (bibliografia no apêndice do manual após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:12</a>; CKopp, The Holy Places of the Gospels, tradução de RWalls, ’63, 143–54; RRiesner, Bibel u. Kirche 43, ’88, 69–71); 4:46. Cidade natal de Natanael 21:2; segundo muitos, também de Simão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:4</a> (veja <span class=\"greek\">Καναναῖος</span>).—Heinz Noetzel, Christus und Dionysus ’60.—EDNT. BHHW II 926. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καναναῖος, ου, ὁ</h1><div class=\"entry-meta\"><span>epíteto masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">cananeu, epíteto do segundo Simão entre os 12 discípulos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:18</a> (em ambas as passagens, sem tradução [assim REB, em contraste com NRSV]; <span class=\"greek\">Κανανίτης</span> é variante textual em ambas). Não designa origem geográfica em Caná (contra Jerônimo) nem significa «cananeu» no sentido étnico, mas deriva do aramaico <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">קַנְאָן</span> «entusiasta, zelota» (cp. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:13</a>, onde ele é chamado <span class=\"greek\">ζηλωτής</span>), provavelmente porque anteriormente pertencera ao partido dos «zelotas» ou «combatentes pela liberdade» (Schürer I 382, 426, 439–41; II 598–606 [lit.]; JKlausner, Jesus v. Naz.2 ’34, 272ff [tradução inglesa 1926, 205f; 284f]; MHengel, D. Zeloten2 ’76 [tradução inglesa The Zealots ’88]; contrariamente a essa interpretação, Bÿrge Salomonsen, NTS 12, ’66, 164–76); veja FBurkitt, Syriac Forms of NT Proper Names 1912, 5, e <span class=\"greek\">Σίμων</span> 2.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κανανίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>gentílico masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">habitante de Caná, cananita. Segundo Estrabão 14, 5, 14 um dos dois estoicos chamados Atenodoro recebeu essa designação para distingui-lo do outro Atenodoro; <span class=\"greek\">ἀπὸ κώμης τινός</span> (Caná, perto de Tarso) foi acrescentado. Numerosos manuscritos substituem o aparentemente incompreensível <span class=\"greek\">Καναναῖος</span> por este termo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:4</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:18</a>. Epíteto do apóstolo Judas em algumas versões saídicas e siríacas de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:22</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κανδάκη, ης, ἡ</h1><div class=\"entry-meta\"><span>título feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Candace (Bíon de Solos [século II a.C.], Aethiopica: 668 Fgm. 1 Jac. [<span class=\"greek\">βασιλέως</span>] <span class=\"greek\">μητέρα καλοῦσι Κ</span>. «chamam Candace à mãe de um rei»; Strabo 17, 1, 54 p. 820; Ps.-Callisth. 3, 18; Cass. Dio 54, 5; Pliny, HN 6, 35, 7; Sb 8366 [inscrição de 109 d.C.]) título da rainha da Etiópia (em monumentos egípcios, é chamada k[e]nt[e]ky) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:27</a>.—RPietschmann, Pauly-W. I 1894, 1095ff; Grohmann, ibid. X/2, 1919, 1858f; WMaxMüller, Aethiopien 1904; GRöder, Klio 12, 1912, 72ff; AWikenhauser, Die Apostelgesch. 1921, 361f; StLösch, TQ 111, 1930, 477–519; BHHW II 930; ADihle, Umstrittene Daten: Wiss. Abhdl. der Arbeitsgemeinschaft … Westfalen 32, ’65, 65–79; IReimer, Women in the Acts of the Apostles ’95.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κανών, όνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e outros; inscrições, papiros, LXX; TestNapht 2:3. Quanto às acepções da palavra [primariamente «vara reta»], veja TZahn, Grundriss d. Gesch. d. ntl. Kanons2 1904, 1ff; HOppel, <span class=\"greek\">ΚΑΝΩΝ</span>: Philol. Suppl. 30, 4, ’37; LWenger, Canon: SBWienAk 220, 2, ’42) as acepções encontradas em nossa literatura são</p><p class=\"entry-text\"> ① instrumento para determinar a qualidade de algo: regra, padrão, norma (Eur., Hec. 602; Demosth. 18, 296; Aeschin., In Ctesiph. 66; Sext. Emp., Log. 2, 3; Ps.-Plut., Consol. ad Ap. 103a; Epict., index Sch.; Lucian, Pisc. 30; UPZ 110, 58 [164 b.c.]; PLond I, 130, 12 p. 133 [I/II a.d.]; 4 Macc 7:21; EpArist 2; Philo; Jos., Ant. 10, 49, C. Ap. 2, 174; TestNapht 2:3) <span class=\"greek\">τῷ κανόνι τούτῳ στοιχεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:16</a> v.l.; <span class=\"greek\">ἔλθωμεν ἐπὶ τὸν τῆς παραδόσεως ἡμῶν κανόνα</span> 1 Cl 7:2 (cf. Epict. 1, 28, 28 <span class=\"greek\">ἔλθωμεν ἐπὶ τοὺς κανόνας</span>; <span class=\"greek\">τὸν κ</span>. <span class=\"greek\">ἀληθείας</span> … , <span class=\"greek\">ὸ̔ν διὰ τοῦ βαπτίσματος εἴληφεν</span> Iren. 1, 9, 4 [Harv. I 88, 1]).</p><p class=\"entry-text\"> ② conjunto de instruções ou formulação para uma atividade, incumbência, regulamentação de serviço público (veja <span class=\"greek\">λειτουργία</span> 1; ins New Docs 1, p. 37, linha 29 <span class=\"greek\">κατὰ πόλιν καὶ κώμην ἔταξα κανόνα τῶν ὑπηρεσιῶν</span> «promulguei nas diferentes cidades e aldeias uma relação dos serviços que julgo conveniente prestar» [tradução de Horsley]) <span class=\"greek\">ἐν τῷ κανόνι τῆς ὑποταγῆς ὐπάρχειν</span> 1 Cl 1:3. <span class=\"greek\">παρεκβαίνειν τὸν ὡρισμένον τῆς λειτουργίας κανόνα</span> 41:1. Semelhantemente, referente à incumbência missionária dada a Paulo, que incluía instruções sobre uma área geográfica <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:13</a>, 15f (s. FStrange, BA 46, ’83, 167f; AdeOliveira, Die Diakonie der Gerechtigkeit und der Versöhnung in der Apologie des 2. Korintherbriefes ’90, 141–42, n. 306: <span class=\"greek\">κ</span>. designa a incumbência missionária do apóstolo). Outros intérpretes (inclusive NRSV e REB) acentuam o componente geográfico e traduzem «esfera (de atuação)», «território», «limite».</p><p class=\"entry-text\"> ③ No segundo século, na igreja cristã, <span class=\"greek\">κ</span>. passou a designar a verdade revelada, a regra de fé (Zahn, RE VI 683ff.—Cp. Philo, Leg. All. 3, 233 <span class=\"greek\">ὁ διαφθείρων τὸν ὑγιῆ κανόνα τῆς ἀληθείας</span>; Synes., Ad. Paeon. 4 p. 310d <span class=\"greek\">τῆς ἀληθείας κανών</span> com referência à matemática; Hippol., Ref. 10, 5, 2). <span class=\"greek\">ἐκκλησιαστικὸς καὶ καθολικὸς κ</span>. EpilMosq 2. <span class=\"greek\">ᾧ παρέλαβε κανόνι</span> segundo a regra que a pessoa recebeu AcPlCor 2:36.—O emprego de <span class=\"greek\">κανών</span> no sentido de «lista» referente às Escrituras canônicas, bem como no de «cânone (sinodal)», é tardio.—RGG3 III, 1116–22. TRE XVII ’88, 562–70. New Docs 2, 88f. DELG (bibliografia). M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καπερναούμ</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">Καφαρναούμ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καπηλεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ésquilo, Heródoto e outros; inscrições, papiros; Philo, Virt. 112, Leg. ad Gai. 203; cf. Dião Crisóstomo 8, 9, substantivado; frequente acerca da exploração de tavernas) comerciar, vender a retalho, negociar como mascate (referente ao comércio varejista; cf. a oposição <span class=\"greek\">καπηλεία</span>–<span class=\"greek\">ἐμπορία</span> Jos., C. Ap. 1, 61) <span class=\"greek\">τὶ</span>, alguma coisa, também figuradamente (Pla., Prot. 5, 313d <span class=\"greek\">οἱ τὰ μαθήματα καπηλεύοντες</span>. Semelhantemente, Nicolau de Damasco: 90 Fgm. 132, 2 Jac.; Iambl., Vi. Pyth. 34, 245; Philostrat., Vi. Apoll. 1, 13 <span class=\"greek\">τὴν σοφίαν καπηλεύειν</span>) <span class=\"greek\">τὸν λόγον τ</span>. <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:17</a> (Anon. Vi. Pla. p. 8, 48 Westerm. <span class=\"greek\">κάπηλος λόγων</span>). Devido às artimanhas dos pequenos comerciantes (Dio Chrys. 14 [31], 37f; Lucian, Hermot. 59 <span class=\"greek\">φιλόσοφοι ἀποδίδονται τὰ μαθήματα ὥσπερ οἱ κάπηλοι</span>, … <span class=\"greek\">δολώσαντες καὶ κακομετροῦντες</span>; Is 1:22 <span class=\"greek\">οἱ κ</span>. <span class=\"greek\">μίσγουσι τ</span>. <span class=\"greek\">οἶνον ὕδατι</span>) a palavra quase chega a significar «adulterar» (assim a Vulgata, a siríaca e a gótica).—Pauly-W. X/2, 1888f.—B. 821. DELG sob o verbete <span class=\"greek\">κάπηλος</span>. M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καπνός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e outros; BGU 1026 XXII, 17; LXX; ApcSed 5:5; Jos., Ant. 5, 284; 12, 310) fumaça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:2f</a>; 18:9, 18. <span class=\"greek\">ἀναβαίνει</span> (Horapollo 2, 16 <span class=\"greek\">εἰς οὐρανόν</span>; Ex 19:18; Josh 8:20; Is 34:10) 8:4; 9:2a; 14:11; 19:3. <span class=\"greek\">καπνὸς καμίνου</span> (Ex 19:18; Job 41:12) 9:2b. Referente à nuvem de fumaça na qual Deus se manifesta (Is 6:4) 15:8. Com fogo e enxofre (veja <span class=\"greek\">θεῖον</span>) 9:17f. Com fogo e sangue <span class=\"greek\">ἀτμὶς καπνοῦ</span> vapor de fumaça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:19</a> (Jo 3:3).—B. 73. DELG. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καππαδοκία, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Menand., Kolax Fgm. 2, 2 S.; Strabo 11, 13, 15–12, 2, 11 al.; TestSim 6:3; Josefo, índice; ins) Capadócia, província no interior da Ásia Menor. Mencionada juntamente com outras regiões da Ásia Menor (Posidon.: 87 Fgm. 36, 50 Jac.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:1</a> (Ps.-Callisth. 2, 11, 1 Alexandre envia uma carta circular [<span class=\"greek\">ἐγκύκλιος ἐπιστολή</span>] a cinco satrapias vizinhas, entre elas a Capadócia).—JMarquardt, Röm. Staatsverwaltung I2 1881, 365ff; Ramsay, Hist. Geogr. 281ff, Church 443ff; EKirsten, Kappadokia ’55. OEANE I 419–22.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καραδοκία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(<span class=\"greek\">κάρα</span>, «cabeça, cume», acrescido de uma forma derivada da raiz de <span class=\"greek\">δέχομαι</span>; Aq Ps 38:8 e Pr 10:28.—<span class=\"greek\">καραδοκέω</span> Eurípides, Heródoto e outros; Jos., Bell. 4, 305; 5, 28, Ant. 17, 86) expectativa ardente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a> variante textual (em lugar de <span class=\"greek\">ἀποκαραδοκία</span>).—DELG sob os verbetes <span class=\"greek\">κάρα</span> e <span class=\"greek\">δεχομαι</span> B.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καρδία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(documentado desde Homero [<span class=\"greek\">καρδίη</span>, <span class=\"greek\">κραδίη</span>]. Relativamente raro em outros escritos no período da Bíblia grega [veja Diod S 32, 20; Plut., Mor. p. 30a; 63a; Epict. 1, 27, 21; M. Ant. 2, 3, 3; 7, 13, 3; Ps.-Apollod. 1, 4, 1, 5; Lucian; papiros, incluindo PGM 5, 157; 13, 263; 833; 1066; veja abaixo 1b<span class=\"greek\">η</span>], mas frequente na LXX e nos pseudoepígrafos; Ar. 15, 3; Just., D. 39, 5; 46, 5 al.; Ath. 31, 3. Quanto a Fílon e Josefo, veja ASchlatter, D. Theol. d. Judentums nach d. Bericht d. Jos. ’32, 21).</p><p class=\"entry-text\"> ① coração como sede da vida física, espiritual e mental (como frequentemente na literatura grega), extensão figurada de «coração» como órgão corporal (Il. 13, 282 al.), acepção não encontrada no corpus aqui estudado</p><p class=\"entry-text\"> ⓐ como centro e fonte da vida física (Ps 101:5; 103:15) <span class=\"greek\">ἐμπιπλῶν τροφῆς</span> … <span class=\"greek\">τὰς κ</span>. saciando os corações com alimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:17</a>. <span class=\"greek\">τρέφειν τὰς κ</span>. engordar os corações <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:5</a>.</p><p class=\"entry-text\"> ⓑ como centro e fonte de toda a vida interior, abrangendo pensamento, sentimento e vontade (<span class=\"greek\">νοῦν κ</span>. <span class=\"greek\">φρένας κ</span>. <span class=\"greek\">διάνοιαν κ</span>. <span class=\"greek\">λογισμὸν εἶπέ τις ποιητὴς</span> [Hes., Fgm. 247 Rz.] <span class=\"greek\">ἐν καρδίᾳ περιέχεσθαι</span>=um poeta afirmou que o coração abrange percepção, engenho, intelecto e reflexão), referente aos seres humanos, tanto em sua experiência anterior ao cristianismo quanto na cristã</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. num sentido abrangente: dito do conhecimento que Deus ou Cristo tem da vida interior dos seres humanos <span class=\"greek\">γινώσκειν τὰς καρδίας</span> (cf. 1 Km 16:7; 1 Ch 28:9; veja também Did., Gen. 170, 24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:15</a>; <span class=\"greek\">δοκιμάζειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:4</a>; <span class=\"greek\">ἐρευνᾶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:23</a> (<span class=\"greek\">νεφροὺς κ</span>. <span class=\"greek\">καρδίας</span> como em Ps 7:10; Jer 17:10; 20:12); <span class=\"greek\">κριτικὸς ἐνθυμήσεων καὶ ἐννοιῶν καρδίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a>; <span class=\"greek\">τὰ κρυπτὰ τῆς κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:25</a> (cf. TestReub 1:4). De modo geral, referente às disposições humanas <span class=\"greek\">ὁ κρυπτὸς τῆς κ</span>. <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:4</a>. <span class=\"greek\">ἐκ καρδίας</span> do fundo do coração = sinceramente (Aristoph., Nub. 86) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:17</a>. Também <span class=\"greek\">ἀπὸ τῶν καρδιῶν</span> (M. Ant. 2, 3, 3 <span class=\"greek\">ἀπὸ καρδίας εὐχάριστος τ</span>. <span class=\"greek\">θεοῖς</span>; Lucian, Jupp. Tr. 19; Is 59:13; La 3:33) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:35</a>. <span class=\"greek\">ἐκ καθαρᾶς καρδίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:22</a>. <span class=\"greek\">ἐξ ὅλης τ</span>. <span class=\"greek\">καρδίας</span> (TestLevi 13:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:37</a> v.l. <span class=\"greek\">Χριστὸν ἁγιάσατε ἐν ταῖς κ</span>. <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:15</a>. Em oposição a <span class=\"greek\">κοιλία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:19</a>. Contraposição de <span class=\"greek\">πρόσωπον</span> e <span class=\"greek\">καρδία</span>, aparência externa e disposição interior do coração (cf. 1 Km 16:7 <span class=\"greek\">ἄνθρωπος ὄψεται εἰς πρόσωπον</span>, <span class=\"greek\">ὁ δὲ θεὸς ὄψεται εἰς καρδίαν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:12</a>. A mesma contraposição <span class=\"greek\">προσώπῳ οὐ καρδίᾳ</span> exteriormente, não interiormente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:17</a>. Como sede da vida interior, em oposição à boca ou aos lábios, que exprimem ou desmentem a vida interior <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:6</a> (ambos citam Is 29:13); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:8</a> (Dt 30:14); vs. 9f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:11</a>. <span class=\"greek\">ψάλλοντες</span> (+ <span class=\"greek\">ἐν</span> v.l.) <span class=\"greek\">τῇ καρδίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:19</a>. <span class=\"greek\">ᾂδειν ἐν ταῖς κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:16</a>.</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. referente à consciência interior (veja o «poeta» sob 1b acima; Aesop, Fab. 254P.=232H//134b H-H.//184 Ch.; 3 Km 10:2; Job 12:3; 17:4): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a>. <span class=\"greek\">τῇ κ</span>. <span class=\"greek\">συνιέναι</span> compreender <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:15b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:27b</a> (ambos citam Is 6:10). <span class=\"greek\">νοεῖν τῇ κ</span>. pensar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40b</a>. <span class=\"greek\">ἐν τῇ κ</span>. <span class=\"greek\">λέγειν</span> (Dt 8:17; 9:4; Ps 13:1. Também em Aesop Fab. 62 H.=283b 5 H-H.//179c Ch. <span class=\"greek\">βοῶν ἐν τῇ καρδίᾳ</span> alternando com <span class=\"greek\">ταῦτα καθ</span>’ <span class=\"greek\">ἑαυτὸν λέγοντος</span>) dizer a si mesmo, isto é, pensar, refletir, sem nada dizer em voz alta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:7</a>; <span class=\"greek\">διαλογίζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:6</a>, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:15</a>; 5:22; Hv 1, 1, 2; 3, 4, 3. O <span class=\"greek\">κ</span>. como fonte dos <span class=\"greek\">διαλογισμοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:35</a>; 9:47. <span class=\"greek\">διαλογισμοὶ ἀναβαίνουσιν ἐν τῇ καρδίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:38</a>. <span class=\"greek\">ἀναβαίνει τι ἐπὶ τὴν καρδίαν τινός</span> algo vem à mente de alguém = alguém pensa em alguma coisa (veja <span class=\"greek\">ἀναβαίνω</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:9</a>; Hv 3, 7, 2; m 12, 3, 5; Hs 5, 7, 2. Também referente à memória Hv 3, 7, 6; m 4, 2, 2; 6, 2, 8. <span class=\"greek\">θέσθαι ἐν τῇ καρδίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.66\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:66</a>. <span class=\"greek\">διατηρεῖν ἐν τ</span>. <span class=\"greek\">καρδίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:51</a> (cf. TestLevi 6:2). <span class=\"greek\">συμβάλλειν</span> vs. 19. <span class=\"greek\">ἐνθυμεῖσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:4</a>. <span class=\"greek\">διακρίνειν</span> Hv 1, 2, 2. <span class=\"greek\">πάντα τὰ ῥήματά μου ἐν καρδίᾳ λαμβάνων</span> guardando no coração todas as minhas palavras AcPl Ha 1, 6.—De modo semelhante, referente à falta de compreensão: <span class=\"greek\">ἡ ἀσύνετος κ</span>. a mente insensata <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:21</a>; <span class=\"greek\">βραδὺς τῇ κ</span>. lento para compreender <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:25</a> (cf. Tetr. Iamb. 2, 31a, 6 as palavras zombeteiras da raposa <span class=\"greek\">ὦ ἀνόητε κ</span>. <span class=\"greek\">βραδὺ τῇ καρδίᾳ</span>). <span class=\"greek\">ἐπαχύνθη ἡ κ</span>. <span class=\"greek\">τοῦ λαοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:15a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:27a</a> (ambos citam Is 6:10). <span class=\"greek\">πωροῦν τὴν κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40a</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">πεπωρωμένη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:52</a>; 8:17; <span class=\"greek\">ἡ πώρωσις τῆς κ</span>. 3:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:18</a>. <span class=\"greek\">ἀπατᾶν καρδίαν αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:26</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:18</a>. <span class=\"greek\">κάλυμμα ἐπὶ τὴν κ</span>. <span class=\"greek\">κεῖται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:15</a> (cf. <span class=\"greek\">ἐστί τι</span> «<span class=\"greek\">κάλλυμα</span>» <span class=\"greek\">ἀγνοίας ἐν τῇ καρδίᾳ</span> Orig., C. Cels. 4, 50, 5).—Como sede do pensamento, <span class=\"greek\">κ</span>. é também a sede da dúvida <span class=\"greek\">διακρίνεσθαι ἐν τῇ κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:23</a>. <span class=\"greek\">διστάζειν</span> Hm 9:5.—O evangelho é semeado no coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:19</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:15</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:12</a>, 15. Deus abre o coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:14</a> ou os olhos do coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:18</a>; 1 Cl 59:3 ao conhecimento cristão.</p><p class=\"entry-text\"> <span class=\"greek\">γ</span>. referente à vontade e às suas decisões (Diod S 32, 20) <span class=\"greek\">ἕκαστος καθὼς προῄρηται τῇ κ</span>. cada um deve contribuir conforme decidiu no coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:7</a> (NRSV) (cf. TestJos 17:3 <span class=\"greek\">ἐπὶ προαιρέσει καρδίας</span>). <span class=\"greek\">θέτε ἐν ταῖς καρδίαις ὑμῶν</span> (veja 1 Km 21:13) tomai vossa decisão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:4</a>. <span class=\"greek\">πρόθεσις τ</span>. <span class=\"greek\">καρδίας</span> 11:23. <span class=\"greek\">βάλλειν εἰς τὴν κ</span>. <span class=\"greek\">ἵνα</span> pôr no coração de alguém a intenção de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:2</a>. Também <span class=\"greek\">διδόναι εἰς τ</span>. <span class=\"greek\">κ</span>. (2 Esdr 17:5) seguido de infinitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:17</a>, ou <span class=\"greek\">πληροῦν τὴν κ</span>. seguido de infinitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:3</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>; 7:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:16</a>; em citação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:8</a>, 15; 4:7 (todos citam Ps 94:8) al. <span class=\"greek\">πλανᾶσθαι τῇ κ</span>. 3:10. A lei de Deus escrita nos corações humanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:2f</a>. Em citação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:10</a>; 10:16 (ambos citam Jr 38:33). Firmeza diante de ensinamentos divergentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:9</a>.</p><p class=\"entry-text\"> <span class=\"greek\">δ</span>. referente às decisões morais, à vida moral, aos vícios e às virtudes: <span class=\"greek\">ἁγνίζειν τὰς κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:8</a>; <span class=\"greek\">καθαρίζειν τὰς κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:9</a>; Hv 3, 9, 8; w. <span class=\"greek\">ἀπό τινος</span> Hm 12, 6, 5; <span class=\"greek\">καθαρὸς τῇ κ</span>. puros de coração (Ps 23:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:8</a>; <span class=\"greek\">καθαρὰ κ</span>. (Sextus 46b) Hv 4, 2, 5; 5:7; m 2:7 cj.; Hs 7:6. <span class=\"greek\">ῥεραντισμένοι τὰς κ</span>. <span class=\"greek\">ἀπὸ συνειδήσεως πονηρᾶς</span> com os corações aspergidos e purificados da consciência de culpa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:22</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἄμεμπτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:13</a>. <span class=\"greek\">ἀμετανόητος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:5</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πονηρὰ ἀπιστίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:12</a>; <span class=\"greek\">λίθιναι κ</span>. B 6:14 (Ezk 36:26). <span class=\"greek\">γεγυμνασμένη πλεονεξίας</span> exercitado na cobiça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:14</a> (cf. <span class=\"greek\">κ</span>. … <span class=\"greek\">ἐπὶ τὸ κακὸν ἔγκειται</span> Did., Gen. 104, 14). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:21f</a>. <span class=\"greek\">περιτομὴ καρδίας</span> (cf. Jer 9:25; Ezk 44:7, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:29</a>.—B 9:1; 10:12. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.51\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:51</a>.</p><p class=\"entry-text\"> <span class=\"greek\">ε</span>. referente às emoções, aos anseios e aos desejos (Theognis 1, 366; Bacchylides 17, 18): <span class=\"greek\">ἐπιθυμίαι τῶν κ</span>. desejos do coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:24</a>. <span class=\"greek\">ἐπὶ τὴν κ</span>. <span class=\"greek\">σου ἀνέβη ἡ ἐπιθυμία τ</span>. <span class=\"greek\">πονηρίας</span> Hv 1, 1, 8; cf. Hs 5, 1, 5. <span class=\"greek\">ἐνθύμησις</span> m 4, 1, 2; 6, 2, 7. <span class=\"greek\">μὴ ἀναβαινέτω σου ἐπὶ τὴν κ</span>. <span class=\"greek\">περὶ γυναικός</span> m 4, 1, 1; cf. Hv 1, 2, 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:28</a>.—6:21; 12:34f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:45</a>; 12:34; 24:32 (veja <span class=\"greek\">καίω</span> 1b); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:14</a>; 5:8. Referente à alegria: <span class=\"greek\">ηὐφράνθη ἡ κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:26</a> (Ps 15:9). <span class=\"greek\">χαρήσεται ἡ κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:22</a>. Referente à tristeza: <span class=\"greek\">ἡ λύπη πεπλήρωκεν τὴν κ</span>. 16:6; <span class=\"greek\">λύπη ἐγκάθηται εἰς τὴν κ</span>. a tristeza está assentada no coração Hm 10, 3, 3. <span class=\"greek\">ἡ κ</span>. <span class=\"greek\">ταράσσεται</span> (Job 37:1; Ps 142:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:1</a>, 27; <span class=\"greek\">ὀδύνη τῇ κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:2</a>. <span class=\"greek\">συνοχὴ καρδίας</span> angústia de coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:4</a>; <span class=\"greek\">διαπρίεσθαι ταῖς κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.54\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:54</a>; <span class=\"greek\">κατανυγῆναι τὴν κ</span>. 2:37; <span class=\"greek\">συνθρύπτειν τὴν κ</span>. 21:13. <span class=\"greek\">κ</span>. <span class=\"greek\">συντετριμμένη</span> coração quebrantado B 2:10; 1 Cl 18:17b (Ps 50:19). <span class=\"greek\">συντετριμμένοι τὴν κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:18</a> v.l. <span class=\"greek\">παρακαλεῖν τὰς κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:2</a>; 4:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:17</a>. Referente à esperança (Ps 111:7) Hm 12, 5, 2. Referente ao arrependimento <span class=\"greek\">ἐξ ὅλης κ</span>. Hv 3, 13, 4; m 5, 1, 7; 12, 6, 1. Referente à sensibilidade moral diante da prática do que é correto (1 Km 24:6; 2 Km 24:10) 1J 3:19, 20, 21 (veja ASkrinjar, Verb. Dom. 20, ’40, 340–50). Referente a um desejo <span class=\"greek\">εὐδοκία τῆς κ</span>. (veja <span class=\"greek\">εὐδοκία</span> 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:1</a>. Referente ao anseio por Deus <span class=\"greek\">τὴν κ</span>. <span class=\"greek\">ἔχειν πρὸς κύριον</span> Hm 10, 1, 6. <span class=\"greek\">ἐπιστρέφεσθαι πρὸς τὸν κύριον ἐξ ὅλης τῆς κ</span>. 12, 6, 2 (cf. 3 Km 8:48). <span class=\"greek\">προσέρχεσθαι μετὰ ἀληθινῆς κ</span>. com desejo sincero (cf. Is 38:3; TestDan 5:3 <span class=\"greek\">ἀλ</span>. <span class=\"greek\">κ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:22</a>. Cf. o sentido contrário <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:39</a>.—Também referente ao desejo ou à vontade de Deus <span class=\"greek\">ἀνὴρ κατὰ τὴν κ</span>. (<span class=\"greek\">τοῦ θεοῦ</span>) segundo o coração de Deus, isto é, conforme Deus deseja que ele seja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:22</a> (cf. 1 Km 13:14).</p><p class=\"entry-text\"> <span class=\"greek\">ζ</span>. especialmente também referente ao amor (Aristoph., Nub. 86 <span class=\"greek\">ἐκ τῆς κ</span>. <span class=\"greek\">φιλεῖν</span>; M. Ant. 7, 13, 3 <span class=\"greek\">ἀπὸ κ</span>. <span class=\"greek\">φιλεῖν τ</span>. <span class=\"greek\">ἀνθρώπους</span>) <span class=\"greek\">ἀγαπᾶν τινα ἐξ ὅλης τ</span>. <span class=\"greek\">καρδίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:30</a>, 33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:27</a> (cf. Dt 6:5 e APF 5, 1913, 393 no. 312, 9 <span class=\"greek\">ἐκ ψυχῆς κ</span>. <span class=\"greek\">καρδίας</span>). <span class=\"greek\">ἐν ὅλῃ τ</span>. <span class=\"greek\">καρδίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:37</a>; <span class=\"greek\">ἐπιστρέψαι καρδίας πατέρων ἐπὶ τέκνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:17</a> (Mal 3:23); <span class=\"greek\">εἶναι ἐν τῇ κ</span>. ter lugar no coração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:3</a>; <span class=\"greek\">ἔχειν τινὰ ἐν τῇ κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:7</a>; Hm 12, 4, 3; Hs 5, 4, 3; cf. m 12, 4, 5; <span class=\"greek\">κατευθύνειν τὰς κ</span>. <span class=\"greek\">εἰς τὴν ἀγάπην τοῦ θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:5</a>.—Em sentido oposto, <span class=\"greek\">κατά τινος ἐν τῇ κ</span>. <span class=\"greek\">ἔχειν</span>, ter algo contra alguém Hv 3, 6, 3.</p><p class=\"entry-text\"> <span class=\"greek\">η</span>. referente à disposição interior (TestJob 48:1 <span class=\"greek\">ἀνέλαβεν ἄλλην κ</span>.) <span class=\"greek\">διάνοια καρδίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:51</a>; <span class=\"greek\">ἁπλότης</span> (<span class=\"greek\">τ</span>.) <span class=\"greek\">καρδίας</span> (TestReub 4:1, Sim 4:5 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:22</a>; <span class=\"greek\">ἀφελότης καρδίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:46</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ ψυχὴ μία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:32</a> (cf. Iren. 1, 10, 2 [Harv. I 92, 5]; a combinação de <span class=\"greek\">ψυχή</span> e <span class=\"greek\">καρδία</span>, como em PGM 7, 472; IDefixWünsch 3, 15; Dt 11:18; 1 Km 2:35; 4 Km 23:3 e frequentemente na LXX — quanto a tais combinações, veja Reader, Polemo p. 260 e cf. Demosth. 18, 220 <span class=\"greek\">ῥώμη καὶ τόλμη</span>). <span class=\"greek\">πραῢς καὶ ταπεινὸς τῇ κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:29</a> (cf. TestReub 6:10). <span class=\"greek\">ἡ εἰρήνη τοῦ Χριστοῦ βραβευέτω ἐν ταῖς κ</span>. <span class=\"greek\">ὑμῶν</span> que a paz de Cristo governe vosso íntimo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:15</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:7</a>.</p><p class=\"entry-text\"> <span class=\"greek\">θ</span>. A <span class=\"greek\">καρδία</span> humana como morada de poderes e seres celestiais (PGM 1, 21 <span class=\"greek\">ἔσται τι ἔνθεον ἐν τῇ σῇ κ</span>.): referente ao Espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:6</a>; referente ao Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:17</a>; referente ao anjo da justiça Hm 6, 2, 3; 5.</p><p class=\"entry-text\"> ② interior, centro, âmago; extensão figurada da acepção 1 (Ezk 27:4, 25; Jon 2:4; Ps 45:3; EpJer 19) <span class=\"greek\">τῆς γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:40</a>.—S., além dos estudos sobre antropologia e psicologia bíblicas (<span class=\"greek\">πνεῦμα</span> end): HKornfeld, Herz u. Gehirn in altjüd. Auffassung: Jahrb. für jüd. Gesch. u. Lit. 12, 1909, 81–89; ASchlatter, Herz. u. Gehirn im 1. Jahrh.: THaering Festschr. 1918, 86–94; RBultmann, Theologie des NT ’48, 216–22 (Paulo), tradução, Theol. of the NT, KGrobel, ’51, I, 220–27; RJewett, Paul’s Anthropological Terms, ’71, 305–33. Quanto às perspectivas do Antigo Testamento, veja RNorth, BRev 11/3, ’95, 33 (bibliografia)—B. 251. EDNT. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καρδιογνώστης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καρδία</span> e <span class=\"greek\">γνώστης</span>; documentado apenas em escritos cristãos, por exemplo em Pseudo-Clemente, Hom. 10, 13; outras referências em Haenchen, comentário ao trecho) conhecedor dos corações, aquele que conhece os corações, dito de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:24</a>; 15:8 (quanto a essas passagens, veja JBauer, BZ 32, ’88, 114–17); Hm 4, 3, 4.—M-M. DELG sob o verbete <span class=\"greek\">γιγνώσκω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καροῦχα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Sym. Is 66:20; Chron. Pasch. 571, 7 LDind. [1832] e em escritores bizantinos) carruagem (na realidade, palavra de origem céltica, latim carruca) MPol 8:2f.—Pauly-W. III 1614f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καρπάσινος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Dionys. Hal. 2, 68, 5; Strabo 7, 2, 3; Esth 1:6) feito de linho fino (latim carbasus; <span class=\"hebrew\" lang=\"he\" dir=\"rtl\">כַּרְפַּס</span>) <span class=\"greek\">λέντιον κ</span>. (variante textual <span class=\"greek\">καρπάσιον</span>) um pano de linho fino Hv 3, 1, 4 (Tibullus 3, 2, 21 carbasea lina).—Pauly-W. III 1572ff. DELG sob o verbete <span class=\"greek\">κάρπασο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κάρπος, ου, ὁ</h1><div class=\"entry-meta\"><span>antropônimo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Artem. 3, 38; SIG2 438, 20; InsHierap 129; moeda de Magnésia [Thieme 40]; papiros [Preisigke, Namenbuch]) Carpo, um cristão em Trôade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:13</a>.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καρπός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(documentado desde Homero) «fruto» (singular usado coletivamente: Diod S 3, 24, 1).</p><p class=\"entry-text\"> ① produto ou resultado de alguma coisa: fruto</p><p class=\"entry-text\"> ⓐ em sentido físico</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. referente às plantas: árvores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:33</a>; 21:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:44</a>; 13:6f; IEph 14:2; Hs 1, 2, 1; 9, 1, 10; 9, 28, 1 e 3 (Did., Gen. 86, 3). Referente ao fruto da videira (Jos., Ant. 2, 67; Ath 22:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:7</a>; 1 Cl 23:4; referente a um arbusto que produz bagas B 7:8. Referente às culturas agrícolas (Diod S 4, 4, 2; Ps.-Phoc. 38; SibOr 4, 16; Hippol., Ref. 7, 29, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:6</a>; 1 Cl 24:4; especificado por <span class=\"greek\">τῆς γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7a</a>; cf. vs. 7b v.l.; 1 Cl 14:1 (Gen 4:3); GJs 3:3. <span class=\"greek\">συνάγειν τοὺς κ</span>. (Lev 25:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:36</a>; <span class=\"greek\">ὅταν παραδοῖ ὁ κ</span>. quando o estado da colheita o permitir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:29</a> («fruto» = cereal, como em Pseudo-Cílax, Peripl. §93 p. 36 Fabr. [<span class=\"greek\">πυροὺς κ</span>. <span class=\"greek\">κριθάς</span>]). <span class=\"greek\">βλαστάνειν τὸν κ</span>. produzir colheitas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:18</a> (veja <span class=\"greek\">βλαστάνω</span> 1). <span class=\"greek\">ποιεῖν κ</span>. (=<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">עָשָׂה פְרִי</span>) dar ou produzir fruto (Gen 1:11f; 4 Km 19:30; Ezk 17:23; ParJer 9:16, 19.—Diosc., Mat. Med. 2, 195) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:10</a> (veja <span class=\"greek\">δένδρον</span>); 7:17ff; 13:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:9</a>; 6:43; 8:8; 13:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2a</a>. Também <span class=\"greek\">διδόναι</span> (=<span class=\"hebrew\" lang=\"he\" dir=\"rtl\">נָתַן פְּרִי</span>; Lev 26:20; Dt 11:17; Ps 1:3; Zech 8:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:7f</a>; B 11:6 (Ps 1:3); Hs 2:4; 5, 2, 4. <span class=\"greek\">φέρειν</span> (Apollon. Rhod. 4, 1396–99b; Jo 2:22; Hos 9:16; Jos., Ant. 3, 11; SibOr 2, 320; Did., Gen. 31, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:18a</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:24</a> (referente à ressurreição: <span class=\"greek\">ἐκφέρει</span> 1 Cl 24:5); 15:2, 4; Hs 2:3, 8a. <span class=\"greek\">ἡ γῆ προφέρει τοὺς κ</span>. <span class=\"greek\">αὐτῆς</span> GJs 8:3. <span class=\"greek\">ἀποδιδόναι</span> dar fruto (Lev 26:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2b</a>; Hs 2:8b; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:11</a>, mas entregar a alguém uma parte do fruto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:41</a>. <span class=\"greek\">γεννᾶν κ</span>. <span class=\"greek\">θανατηφόρον</span> produzir fruto mortal ITr 11:1 (em sentido figurado, veja b abaixo). <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span> referente a árvores Hs 9, 28, 3; referente a varas 8, 1, 18; 8, 2, 1; 8, 3, 7; 8, 4, 6; 8, 5, 6; referente à vara de Arão (Num 17:23ff) 1 Cl 43:5.</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. referente ao ser humano: em hebraísmo, acerca da descendência <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">τῆς κοιλίας</span> o fruto do ventre (Gen 30:2; Ps 131:11; Mi 6:7; La 2:20; TestAbr A 6 p. 83, 14 [Stone p. 14]; Mel., P. 52, 384 [como o significado central de <span class=\"greek\">κοιλία</span> é algo «oco», nas passagens dos Salmos e de Miqueias <span class=\"greek\">κοιλία</span> é empregado no sentido geral de «corpo», como cavidade da qual procede alguma coisa]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:42</a>. <span class=\"greek\">τοῦ μὴ δοῦναί σοι καρπόν</span>=não te conceder filhos GJs 2:3; cf. 6:3 (veja b abaixo). Sob a perspectiva do pai: <span class=\"greek\">ὁ κ</span>. <span class=\"greek\">τῆς ὀσφύος</span> o fruto de seus lombos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:30</a>; AcPl Ha 8, 14 (<span class=\"greek\">ἰσχύος</span> Ox 1602, 12f//BMM recto 17).</p><p class=\"entry-text\"> ⓑ figuradamente, no âmbito espiritual (em oposição ao físico); por vezes a imagem original é bastante evidente, outras vezes mais ou menos atenuada: resultado, consequência, produto (cf. Epict. 2, 1, 21 <span class=\"greek\">τῶν δογμάτων καρπός</span>; IPriene 112, 14 [I b.c.] <span class=\"greek\">μόνη μεγίστους ἀποδίδωσιν καρπούς</span>; Dio Chrys. 23 [40], 34 <span class=\"greek\">τῆς ἔχθρας καρπός</span>) <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:22</a> (uma lista de virtudes que sucede a uma lista de vícios como em Cebes 19, 5; 20, 3; Ael. Aristid. 37, 27 K.=2 p. 27 D.). <span class=\"greek\">τοῦ φωτός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:9</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">πολὺν φέρειν</span> produzir muito fruto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:5</a>, 8, 16. <span class=\"greek\">κ</span>. <span class=\"greek\">δικαιοσύνης</span> fruto de justiça (cf. Epicurus, Fgm. 519 <span class=\"greek\">δικαιοσύνης καρπὸς μέγιστος ἀταραξία</span>; Am 6:12; Pr 11:30; 13:2; EpArist 232) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:18</a>; Hs 9, 19, 2a; cf. <span class=\"greek\">ἔδωκέν μοι κύριος</span> … <span class=\"greek\">καρπὸν δικαιοσύνης αὐτοῦ</span> GJs 6:3 (referente ao nascimento de Maria; veja <span class=\"greek\">β</span> acima); <span class=\"greek\">κ</span>. <span class=\"greek\">εἰρηνικὸς δικαιοσύνης</span> fruto pacífico de justiça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:11</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀληθείας</span> Hs 9, 19, 2b. O resultado da ação é uma obra: <span class=\"greek\">ἀπὸ τῶν καρπῶν τινος ἐπιγινώσκειν τινά</span> reconhecer alguém por suas obras, assim como se conhece a árvore pelos frutos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:16</a>, 20; Hs 4:5 (Proverbia Aesopi 51 P.: <span class=\"greek\">Δῆλος ἔλεγχος ὁ καρπὸς γενήσεται</span> | <span class=\"greek\">παντὸς δένδρου ἣν ἔχει φύσιν</span>=seu fruto constituirá prova clara da natureza de cada árvore). <span class=\"greek\">γεννᾶν καρπὸν θανατηφόρον</span> produzir fruto mortal ITr 11:1 (veja 1a<span class=\"greek\">α</span>); a conduta moral entendida como fruto vs. 2 (segundo a imagem, os cristãos são ramos da cruz, que lhes serve de tronco, e suas obras são os frutos). Fruto do martírio Hs 9, 28, 4. <span class=\"greek\">ποιεῖν τοὺς καρποὺς αὐτῆς</span> (=<span class=\"greek\">τῆς βασιλείας τ</span>. <span class=\"greek\">θεοῦ</span>) produzir fruto para o reino <span class=\"greek\">ποιεῖν καρπὸν ἄξιον τῆς μετανοίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:43</a>. produzir fruto condizente com o arrependimento 3:8; o plural no paralelo de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:8</a> se afasta mais da imagem original: <span class=\"greek\">καρποί</span> = <span class=\"greek\">ἔργα</span> (cf. Pr 10:16). <span class=\"greek\">καρποὶ ἀγαθοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:17</a>. Cf. Dg 12:1. <span class=\"greek\">τίνα καρπὸν ἄξιον</span> … (<span class=\"greek\">δώσομεν</span>); que fruto (devemos apresentar a Cristo que seja) digno do que ele nos concedeu? 2 Cl 1:3. Referente ao resultado de uma vida no pecado e também na justiça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:21f</a> (quanto aos resultados do mal, por exemplo, Oenomaus Fgm. 2m [em Eus., PE 5, 20, 10]); <span class=\"greek\">ταχὺς κ</span>. (veja <span class=\"greek\">ταχ</span>. 1a) 2 Cl 20:3. Depois de uma vida íntegra <span class=\"greek\">καρπὸν προσδοκῶν</span> Dg 12:6; cf. 12:8; a ressurreição como recompensa após uma vida atribulada <span class=\"greek\">ἔδονται τῆς ἑαυτῶν ὁδοῦ τοὺς κ</span>. 2 Cl 19:3.—<span class=\"greek\">ἀφ</span>’ <span class=\"greek\">οὗ καρποῦ ἡμεῖς</span> (o sofrimento de Jesus), o fruto do qual procedemos, isto é, do qual provém nossa identidade como cristãos (a cruz é aqui representada como árvore, na qual Jesus pende como fruto; Inácio provavelmente concebe os cristãos como sementes germinadas) ISm 1:2.—Referente ao produto de uma coleta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:28</a>.</p><p class=\"entry-text\"> ⓒ Em hebraísmo, oferta de louvor como <span class=\"greek\">καρπὸς χειλέων</span> (Hos 14:3; Pr 18:20; 31:31 v.l.; PsSol 15:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:15</a>.</p><p class=\"entry-text\"> ② vantagem, ganho, proveito (Polyaenus 3, 9, 1 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς ἀνδραγαθίας</span>; EpArist 260 <span class=\"greek\">σοφίας κ</span>.; Philo, Fug. 176 <span class=\"greek\">ἐπιστήμης</span>; Jos., Ant. 20, 48 <span class=\"greek\">εὐσεβείας</span>) <span class=\"greek\">κ</span>. <span class=\"greek\">ἔργου</span> ganho do trabalho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:22</a>. <span class=\"greek\">οὐ δόμα</span>, <span class=\"greek\">ἀλλὰ τὸν καρπόν</span> não a dádiva, mas o proveito (que advém aos filipenses de sua generosidade) 4:17; <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span> obter fruto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:13</a>.—B. 511. DELG 1 <span class=\"greek\">καρπός</span>. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καρποφορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καρπός</span> e <span class=\"greek\">φέρω</span>) futuro <span class=\"greek\">καρποφορήσω</span>; 1º aoristo <span class=\"greek\">ἐκαρποφόρησα</span></p><p class=\"entry-text\"> ① produzir frutos ou sementes, dar fruto, produzir colheita, literalmente (Xenofonte e outros; Theophr., HP 3, 3, 7; Diod S 2, 49, 4; PMichZen106, 6 [século III a.C.]; Wsd 10:7; Hab 3:17; En 5:1; Just., D. 110, 4) referente à terra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:28</a> (<span class=\"greek\">γῆ κ</span>. como em Josefo, C. Ap. 1, 306; Did., Gen. 31, 14). Referente a uma videira Hs 2:3.</p><p class=\"entry-text\"> ② tornar produtiva a vida interior, frutificar (Philo, Cher. 84 <span class=\"greek\">κ</span>. <span class=\"greek\">ἀρετάς</span>; Did., Gen. 32, 24; quanto à construção com acusativo, cf. Hippol., Ref. 6, 46, 3; em uso absoluto, OdeSol 11:23; cf. SEG XLII, 1193, 8 e 1421, 4 ambos cristãos, século V d.C.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:15</a>; Hs 4:5, 8. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν τῇ καρδίᾳ</span> produzir fruto no coração, isto é, na disposição de fazer o que é correto B 11:11; cf. <span class=\"greek\">ἐν σεαυτῷ</span> Hs 4:5. Referente à fé <span class=\"greek\">τῆς πίστεως ῥίζα καρποφορεῖ εἰς τὸν κύριον ἡμῶν Ἰησοῦν Χριστόν</span> a raiz da fé produz fruto em (ou para) nosso Senhor Jesus Cristo Pol 1:2. Com dativo de interesse <span class=\"greek\">κ</span>. <span class=\"greek\">τῷ θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:4</a> (so OdeSol 11:1). Também <span class=\"greek\">τῷ θανάτῳ</span> vs. 5. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν παντὶ ἔργῳ ἀγαθῷ</span> produzir fruto em toda espécie de boas obras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:10</a>.—Na voz média (IBM 918), frutificar por si mesmo 1:6.—DELG sob o verbete <span class=\"greek\">φέρω</span> p. 1190. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καρποφόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καρποφορέω</span>; Píndaro, Heródoto e posteriores; inscrições; PSI 171, 40 [século II a.C.]; Papiros gregos de Avroman: JHS 35, 1915, 22ff, no. 1 A, 13 [88 a.C.]; Sb 991, 5; 6598, 7; LXX; OdeSol 11:16a; TestSol C prol. 3; JosAs 2:19; ch. 16 cod. A [p. 65, 17 Bat.]; Philo; Jos., Bell. 3, 44, Ant. 4, 85; Just., D. 110, 4; SibOr, Fgm. 3, 5) frutífero, que produz fruto <span class=\"greek\">καιροὶ κ</span>. (veja <span class=\"greek\">καιρός</span> 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:17</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:2</a> D.—DELG sob o verbete <span class=\"greek\">φέρω</span> p. 1190. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καρτερέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">κράτος</span>) futuro <span class=\"greek\">καρτερήσω</span> LXX; 1º aoristo <span class=\"greek\">ἐκαρτέρησα</span> (Sófocles, Tucídides e outros; papiros, LXX; TestJob 4:10; Jos., Ant. 11, 52) permanecer sem vacilar numa situação ou condição: ser forte, permanecer firme, perseverar, resistir, suportar (Thu. 2, 44, 3; Pla., Theaet. 157d, Lach. 193a; Diod S 3, 5, 3 <span class=\"greek\">καρτερῆσαι μέχρι τῆς τελευτῆς</span>; PGrenf I, 1, 19 [II b.c.]; PAmh 130, 6; Job 2:9; Sir 2:2; 12:15; 2 Macc 7:17 al.) <span class=\"greek\">τὸν ἀόρατον ὡς ὁρῶν ἐκαρτέρησεν</span> ele perseverou como se visse aquele que é invisível <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:27</a>. Cf. Windisch; Strathmann.—GWhitaker, em ET 27, 1916, 186 prefere a acepção «fixar os olhos em», com base em certas passagens de Plutarco.—Entretanto, a compreensão adequada da palavra deve partir do fato de que o particípio junto de <span class=\"greek\">καρτερεῖν</span> não designa uma circunstância concomitante, mas a disposição com que alguém suporta algo ou permanece firme (Diod S 8, 18, 3 <span class=\"greek\">τοιοῦτον βίον ζῶντα καρτερεῖν</span>=continuar levando uma vida assim; 14, 65, 4 <span class=\"greek\">μέχρι τίνος καρτερήσομεν ταῦτα πάσχοντες</span>;=até quando continuaremos sofrendo isto?; 18, 60, 1 <span class=\"greek\">καρτερεῖν δεσποζόμενος</span>=permitir-se continuar sob domínio; Arrian., Anab. 7, 8, 3 <span class=\"greek\">οὔκουν σιγῇ ἔχοντες ἐκαρτέρησαν</span>=eles, portanto, não permaneceram em silêncio; Ps.-Dicaearchus p. 141 ln. 11 F. <span class=\"greek\">ἀκούων καρτ</span>.=escutar continuamente). Desse modo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:27</a> apresenta o motivo da ausência de temor de Moisés: ele mantinha continuamente diante dos olhos aquele que é invisível (isto é, pela fé), por assim dizer.—DELG sob o verbete <span class=\"greek\">κράτος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0186-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">[ἀπὸ] Καρυώτου</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">veja <span class=\"greek\">Ἰσκαριώθ</span>.</p></section></article>\n"};
